import { makeAutoObservable, configure } from "mobx";
configure({
  enforceActions: "never",
});
class ModalStore {
  visible = false;
  constructor() {
    makeAutoObservable(this);
  }
  setvisible() {
    this.visible = !this.visible;
  }
}
export default new ModalStore();
